import std.collection.HashMap
import std.time.DateTime
import std.logging.Logger

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request["path"] as String
        let method = request["method"] as String

        if (self.is_start_with(request_uri)) {
            return true
        }

        try {
            let token = self.get_jwt_user(request)
            match (token) {
                case Some(t) => {
                    let user = t["user"] as HashMap<String, Any>
                    if (user["level"] as Int64 > 2) {
                        self.set_current_user_info_and_log(user)
                        return true
                    }
                }
                case None => return false
            }
        } catch {
            return false
        }
        return false
    }

    public func is_start_with(request_uri: String): Bool {
        let start_with = ["/api", "/login"]
        for (s in start_with) {
            if (request_uri.startsWith(s)) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any>
        let token = headers["Authorization"] as HashMap<String, Any>
        let user = token["user"] as HashMap<String, Any>

        if (token["jwt"] as String.startsWith(user["name"] as String)) {
            let jwt_str_date = (token["jwt"] as String).split(user["name"] as String)[1]
            let jwt_date = DateTime.parse(jwt_str_date, "yyyy-MM-dd")
            let today = DateTime.now()
            if (today - jwt_date >= Duration.fromDays(3)) {
                return None<HashMap<String, Any>>
            }
        }
        return Some(token)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let host = user["address"] as String
        Logger.log(msg: "${user["name"] as String}${host}${DateTime.now()}", level: Logger.LogLevel.INFO)
    }
}

import std.math.*

class AreaCalculator {
    let radius: Float64

    public init(radius: Float64) {
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        PI * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        4.0 * PI * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        2.0 * PI * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        this.radius * this.radius * angle / 2.0
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        PI * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

