class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let args = command_string.split(" ")[1..]
        var i: Int64 = 0
        while (i < args.size) {
            let arg = args[i]
            if (arg.startsWith("--")) {
                let key_value = arg[2..].split("=")
                if (key_value.size == 2) {
                    arguments.add(key_value[0], convert_type(key_value[0], key_value[1]))
                } else {
                    arguments.add(key_value[0], true)
                }
            } else if (arg.startsWith("-")) {
                let key = arg[1..]
                if (i + 1 < args.size && !args[i + 1].startsWith("-")) {
                    arguments.add(key, convert_type(key, args[i + 1]))
                    i += 1
                } else {
                    arguments.add(key, true)
                }
            }
            i += 1
        }
        let missing_args = HashSet<String>(required.difference(Set<String>(arguments.keySet())))
        if (missing_args.size > 0) {
            return (false, Some<HashSet<String>>(missing_args))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        match (arguments.get(key)) {
            case Some<Any>(value) => value
            case None<Any> => None<Any>
        }
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            required.add(arg)
        }
        types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        match (types.get(arg)) {
            case Some<TypeInfo>(type_info) => {
                match (type_info) {
                    case TypeInfo.of<Int64>() => value.toInt64() ?? value
                    case TypeInfo.of<Int32>() => value.toInt32() ?? value
                    case TypeInfo.of<Float64>() => value.toFloat64() ?? value
                    case TypeInfo.of<Bool>() => value.toLower() == "true"
                    case _ => value
                }
            }
            case None<TypeInfo> => value
        }
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let actual_m = m.getOrElse(n)
        if (n == actual_m) {
            return ArrangementCalculator.factorial(n)
        } else {
            return ArrangementCalculator.factorial(n) / ArrangementCalculator.factorial(n - actual_m)
        }
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n+1) {
            total += ArrangementCalculator.count(n, Some(i))
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let actual_m = m.getOrElse(this.datas.size)
        let result = ArrayList<ArrayList<Int64>>()
        this.select_permutations(ArrayList<Int64>(), ArrayList<Int64>(this.datas), actual_m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..this.datas.size+1) {
            result.addAll(this.select(Some(i)))
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        for (i in 2..n+1) {
            result *= i
        }
        return result
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class AssessmentSystem {
    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String,grade: Int64,major: String): Unit {
        this.students.add(name, Student(name,grade,major))
    }

    public func add_course_score(name: String,course: String,score: Int64): Unit {
        if (this.students.contains(name)) {
            this.students[name].cources.add(course,score)
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name) || this.students[name].cources.size == 0) {
            return None<Float64>()
        }
        var total: Int64 = 0
        for ((_,score) in this.students[name].cources) {
            total += score
        }
        return Some<Float64>(total.toFloat64() / this.students[name].cources.size.toFloat64())
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let result = ArrayList<String>()
        for ((name,student) in this.students) {
            for ((_,score) in student.cources) {
                if (score < 60) {
                    result.add(name)
                    break
                }
            }
        }
        return result
    }

    public func get_course_average(course: String): Option<Float64> {
        var total: Int64 = 0
        var count: Int64 = 0
        for ((_,student) in this.students) {
            if (student.cources.contains(course)) {
                total += student.cources[course]
                count += 1
            }
        }
        if (count == 0) {
            return None<Float64>()
        }
        return Some<Float64>(total.toFloat64() / count.toFloat64())
    }

    public func get_top_student(): Option<String> {
        var top_student: Option<String> = None<String>()
        var top_gpa: Float64 = 0
        for ((name,_) in this.students) {
            let gpa = this.get_gpa(name)
            if (gpa is Some<Float64>) {
                let gpa_value = gpa.getOrThrow()
                if (top_student is None<String>() || gpa_value > top_gpa) {
                    top_gpa = gpa_value
                    top_student = Some<String>(name)
                }
            }
        }
        return top_student
    }
}

