class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64,ay: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        let mut num_buffer = ""

        for char in expression.runes() {
            if char.isDigit() || char == '.' {
                num_buffer += char.toString()
            } else {
                if num_buffer != "" {
                    operand_stack.add(num_buffer.toFloat64())
                    num_buffer = ""
                }

                let op = char.toString()
                if op == "+" || op == "-" || op == "*" || op == "/" || op == "^" {
                    while (
                        !operator_stack.isEmpty() &&
                        operator_stack[operator_stack.size - 1] != "(" &&
                        precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)
                    ) {
                        (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                    }
                    operator_stack.add(op)
                } else if op == "(" {
                    operator_stack.add(op)
                } else if op == ")" {
                    while !operator_stack.isEmpty() && operator_stack[operator_stack.size - 1] != "(" {
                        (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                    }
                    if !operator_stack.isEmpty() {
                        operator_stack.remove(at: operator_stack.size - 1)
                    }
                }
            }
        }

        if num_buffer != "" {
            operand_stack.add(num_buffer.toFloat64())
        }

        while !operator_stack.isEmpty() {
            (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
        }

        if operand_stack.isEmpty() {
            return None<Float64>()
        } else {
            return Some<Float64>(operand_stack[operand_stack.size - 1])
        }
    }

    public func precedence(op: String): Int64 {
        if op == "+" || op == "-" {
            return 1
        } else if op == "*" || op == "/" {
            return 2
        } else if op == "^" {
            return 3
        } else {
            return 0
        }
    }

    public func apply_operator(
        operand_stack: ArrayList<Float64>,
        operator_stack: ArrayList<String>
    ): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack.remove(at: operator_stack.size - 1)
        let operand2 = operand_stack.remove(at: operand_stack.size - 1)
        let operand1 = operand_stack.remove(at: operand_stack.size - 1)
        let result = operators[op].getOrThrow()(operand1, operand2)
        operand_stack.add(result)
        return (operand_stack, operator_stack)
    }
}

