class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (let i = 0; i < this.events.size; i++) {
            if (this.events[i] == event) {
                this.events.remove(at: i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (let event in this.events) {
            if (event.date.dayOfMonth == date.dayOfMonth && 
                event.date.month == date.month && 
                event.date.year == date.year) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (let event in this.events) {
            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let available_slots = ArrayList<(DateTime, DateTime)>()
        let start_time = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let end_time = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 23, minute: 59)

        let slot_start = start_time
        while (slot_start < end_time) {
            let slot_end = slot_start + TimeSpan(minutes: 60)
            if (this.is_available(slot_start, slot_end)) {
                available_slots.add((slot_start, slot_end))
            }
            slot_start += TimeSpan(minutes: 60)
        }
        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()
        let sorted_events = ArrayList<Event>(this.events)

        let compare = {a: Event, b: Event => a.start_time < b.start_time}
        sort(sorted_events, lessThan: compare)

        for (let event in sorted_events) {
            if (event.start_time >= now && upcoming.size < num_events) {
                upcoming.add(event)
            }
        }
        return upcoming
    }
}

import std.collection.HashMap

class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let convKey = (_convert_key(key) as String) ?? key
        return _data[convKey] ?? Nothing()
    }

    public func __setitem__(key: String, value: Any): Unit {
        let convKey = (_convert_key(key) as String) ?? key
        _data.add(convKey, value)
    }

    public func __delitem__(key: String): Unit {
        let convKey = (_convert_key(key) as String) ?? key
        _data.remove(convKey)
    }

    public func __len__(): Int64 {
        return _data.size
    }

    public func _convert_key(key: Any): Any {
        match (key) {
            case s: String => CamelCaseMap._to_camel_case(s)
            case _ => key
        }
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split("_")
        if (parts.size == 0) {
            return ""
        }
        var result = parts[0]
        for (i in 1..parts.size) {
            if (parts[i].size > 0) {
                let firstChar = parts[i][0].toUpperCase()
                let rest = if (parts[i].size > 1) { parts[i].substring(1) } else { "" }
                result = result + firstChar + rest
            }
        }
        return result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            return ArrayList<Int64>()
        }

        var sieve = ArrayList<Bool>([])
        for (_ in 0..(n + 1)) {
            sieve.add(true)
        }
        sieve[0] = false
        sieve[1] = false

        var p: Int64 = 2
        while (p * p <= n) {
            if (sieve[p]) {
                var i = p * p
                while (i <= n) {
                    sieve[i] = false
                    i += p
                }
            }
            p += 1
        }

        var result = ArrayList<Int64>()
        for (i in 2..(n + 1)) {
            if (sieve[i]) {
                result.add(i)
            }
        }

        return result
    }

    public func get_primes(): ArrayList<Int64> {
        return primes
    }
}

