class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        for s in this.students {
            if s["name"] == student["name"] {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if this.students_registration_classes.contains(student_name) {
            let classes = this.students_registration_classes[student_name]
            classes.add(class_name)
        } else {
            let classes = ArrayList<String>([class_name])
            this.students_registration_classes.add(student_name, classes)
        }
        return this.students_registration_classes[student_name]
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let student_list = ArrayList<String>()
        for student in this.students {
            if student["major"] == major {
                student_list.add(student["name"])
            }
        }
        return student_list
    }

    public func get_all_major(): ArrayList<String> {
        let major_list = ArrayList<String>()
        for student in this.students {
            let major = student["major"]
            if !major_list.contains(major) {
                major_list.add(major)
            }
        }
        return major_list
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_list = ArrayList<String>()
        for student in this.students {
            if student["major"] == major {
                if let classes = this.students_registration_classes.get(student["name"]) {
                    class_list.addAll(classes)
                }
            }
        }

        let count_map = HashMap<String, Int64>()
        for class_name in class_list {
            if count_map.contains(class_name) {
                count_map[class_name] = count_map[class_name] + 1
            } else {
                count_map.add(class_name, 1)
            }
        }

        var max_count: Int64 = 0
        var popular_class = ""
        for entry in count_map {
            if entry.value > max_count {
                max_count = entry.value
                popular_class = entry.key
            }
        }
        return popular_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {
    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m == 0 || n == m) {
            return 1
        }
        return factorial(n) / (factorial(n - m) * factorial(m))
    }

    public static func count_all(n: Int64): Int64 {
        if (n < 0 || n > 63) {
            return 0
        }
        if (n == 63) {
            return Int64.Max
        }
        return (1 << n) - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let emptyList = ArrayList<String>()
        for (_ in 0..m) {
            emptyList.add("")
        }
        _select(0, emptyList, 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 1..datas.size + 1) {
            result.addAll(select(i))
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        let resultLen = resultList.size
        let resultCount = resultIndex + 1
        if (resultCount > resultLen) {
            result.add(ArrayList<String>(resultList))
            return
        }

        for (i in dataIndex..datas.size + resultCount - resultLen) {
            resultList[resultIndex] = datas[i]
            _select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

import std.math.abs

class ComplexNumber <: Equatable<ComplexNumber> {
    public var real: Float64
    public var imaginary: Float64

    public init(real: Float64, imaginary: Float64) {
        this.real = real
        this.imaginary = imaginary
    }

    public override operator func != (that: ComplexNumber): Bool {
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        return this.real == that.real && this.imaginary == that.imaginary
    }
}

class ComplexCalculator {
    public init() { }

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let real = c1.real + c2.real
        let imaginary = c1.imaginary + c2.imaginary
        return ComplexNumber(real: real, imaginary: imaginary)
    }

    public static func subtract(c1: Complex Number, c2: ComplexNumber): ComplexNumber {
        let real = c1.real - c2.real
        let imaginary = c1.imaginary - c2.imaginary
        return ComplexNumber(real: real, imaginary: imaginary)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let real = c1.real * c2.real - c1.imaginary * c2.imaginary
        let imaginary = c1.real * c2.imaginary + c1.imaginary * c2.real
        return ComplexNumber(real: real, imaginary: imaginary)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let denominator = c2.real * c2.real + c2.imaginary * c2.imaginary
        let real = (c1.real * c2.real + c1.imaginary * c2.imaginary) / denominator
        let imaginary = (c1.imaginary * c2.real - c1.real * c2.imaginary) / denominator
        return ComplexNumber(real: real, imaginary: imaginary)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        let file = try File(file_name).readString().getOrThrow()
        let lines = file.split("\n")

        if (lines.size > 0) {
            title.addAll(lines[0].split(","))
        }

        for (i in 1..lines.size) {
            let row = ArrayList<String>()
            row.addAll(lines[i].split(","))
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File(file_name).openWrite()
            for row in data {
                let line = row.join(",")
                writeln(file, line)
            }
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, original_data) = read_csv(save_file_name)
        let column_data = ArrayList<ArrayList<String>>()

        column_data.add(title)

        let processed_column = ArrayList<String>()
        for row in original_data {
            if (row.size > N) {
                processed_column.add(row[N].toUpper())
            }
        }

        column_data.add(processed_column)

        let new_file_name = save_file_name.split(".")[0] + "_process.csv"
        return write_csv(column_data, new_file_name)
    }
}

