class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let sum = data.reduce(0, {acc, x => acc + x})
        return round(sum.toFloat64() / data.size.toFloat64(), 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = data.clone()
        sort(sorted_data)
        let n = sorted_data.size
        if (n % 2 == 0) {
            let middle = n / 2
            return round((sorted_data[middle - 1] + sorted_data[middle]).toFloat64() / 2.0, 2)
        } else {
            let middle = n / 2
            return sorted_data[middle].toFloat64()
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counter = HashMap<Int64, Int64>()
        for (x in data) {
            let count = counter.get(x) ?? 0
            counter.add(x, count + 1)
        }

        let max_count = counter.values().reduce(0, {acc, count => if (count > acc) { count } else { acc }})
        let modes = ArrayList<Int64>()
        for ((x, count) in counter) {
            if (count == max_count) {
                modes.add(x)
            }
        }
        return modes
    }
}

import std.collection.ArrayList
