class DataStatistics2 {
    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        var min = data[0]
        for (i in 1..data.size) {
            if (data[i] < min) {
                min = data[i]
            }
        }
        return min
    }

    public func get_max(): Float64 {
        var max = data[0]
        for (i in 1..data.size) {
            if (data[i] > max) {
                max = data[i]
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let mean = get_sum() / data.size.toFloat64()
        var variance = 0.0
        for (i in 0..data.size) {
            variance += (data[i] - mean) * (data[i] - mean)
        }
        variance /= data.size.toFloat64()
        return round(variance, digits: 2)
    }

    public func get_std_deviation(): Float64 {
        let variance = get_variance()
        return round(sqrt(variance), digits: 2)
    }

    public func get_correlation(): Float64 {
        // For single-column data, correlation with itself is always 1.0
        return 1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        let mean1 = data1.sum() / n.toFloat64()
        let mean2 = data2.sum() / n.toFloat64()

        let numerator = (0..n).sum({i: Int64 => (data1[i] - mean1) * (data2[i] - mean2)})
        let denominator = sqrt((0..n).sum({i: Int64 => (data1[i] - mean1).pow(2)})) * 
                         sqrt((0..n).sum({i: Int64 => (data2[i] - mean2).pow(2)}))

        return if (denominator != 0.0) { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.sum() / n.toFloat64()
        let variance = data.sum({x: Float64 => (x - mean).pow(2)}) / n.toFloat64()
        let std_deviation = sqrt(variance)

        return if (std_deviation != 0.0) {
            data.sum({x: Float64 => (x - mean).pow(3)}) * n.toFloat64() / 
            ((n - 1).toFloat64() * (n - 2).toFloat64() * std_deviation.pow(3))
        } else {
            0.0
        }
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.sum() / n.toFloat64()
        let std_dev = sqrt(data.sum({x: Float64 => (x - mean).pow(2)}) / n.toFloat64())

        if (std_dev == 0.0) {
            return Float64.NaN
        }

        let fourth_moment = data.sum({x: Float64 => (x - mean).pow(4)}) / n.toFloat64()
        return (fourth_moment / std_dev.pow(4)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let constant = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        return data.map({x: Float64 => 
            constant * exp(-0.5 * ((x - mu) / sigma).pow(2))
        })
    }
}

extension ArrayList<T> {
    func sum(): Float64 where T: Float64 {
        var total = 0.0
        for (x in this) {
            total += x
        }
        return total
    }

    func sum(fn: (T) -> Float64): Float64 where T: Float64 {
        var total = 0.0
        for (x in this) {
            total += fn(x)
        }
        return total
    }
}

import std.collection.ArrayList

class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let plaintext = ArrayList<Rune>()
        for char in ciphertext.runes() {
            if (char.isAlpha()) {
                let ascii_offset = if (char.isUpper()) { r'A' } else { r'a' }
                let shifted_char = Rune.fromInt((char.toInt() - ascii_offset.toInt() - shift).mod(26) + ascii_offset.toInt())
                plaintext.add(shifted_char)
            } else {
                plaintext.add(char)
            }
        }
        return plaintext.toRuneArray().toString()
    }

    public func vigenere_decipher(ciphertext: String): String {
        let decrypted_text = ArrayList<Rune>()
        var key_index = 0
        for char in ciphertext.runes() {
            if (char.isAlpha()) {
                let shift = (this.key.runes()[key_index.mod(this.key.size)].toLower().toInt() - r'a'.toInt())
                let decrypted_char_code = (char.toLower().toInt() - r'a'.toInt() - shift).mod(26) + r'a'.toInt()
                let decrypted_char = Rune.fromInt(decrypted_char_code)
                decrypted_text.add(if (char.isUpper()) { decrypted_char.toUpper() } else { decrypted_char })
                key_index = key_index + 1
            } else {
                decrypted_text.add(char)
            }
        }
        return decrypted_text.toRuneArray().toString()
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let n = encrypted_text.size
        let fence_chars = Array<Array<Option<Rune>>>(rails, { _ => Array<Option<Rune>>(n, { _ => None<Rune>() }) })
        var direction = -1
        var row = 0
        var col = 0

        for _ in 0..n {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            col = col + 1
            row = row + direction
        }

        var index = 0
        for i in 0..rails {
            for j in 0..n {
                if (fence_chars[i][j] == None<Rune>()) {
                    fence_chars[i][j] = Some<Rune>(encrypted_text.runes()[index])
                    index = index + 1
                }
            }
        }

        let plain_text = ArrayList<Rune>()
        direction = -1
        row = 0
        col = 0
        for _ in 0..n {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            plain_text.add(fence_chars[row][col].getOrThrow())
            col = col + 1
            row = row + direction
        }

        return plain_text.toRuneArray().toString()
    }
}

