        var discount: Float64 = 0.0
        for (item in order.cart) {
            if (item.quantity >= 20) {
                discount += item.quantity * item.price * 0.1
            }
        }
        return discount
    }

    public static func LargeOrderPromo(order: DiscountStrategy): Float64 {
        var productSet = HashSet<String>()
        for (product in order.cart) {
            productSet.add(product.name)
        }
        if (productSet.size >= 10) {
            return order.total() * 0.07
        } else {
            return 0.0
        }
    }
}

import std.collection.ArrayList

class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>,direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }

        if (direction == "up") {
            new_state[i][j] = new_state[i - 1][j]
            new_state[i - 1][j] = 0
        } else if (direction == "down") {
            new_state[i][j] = new_state[i + 1][j]
            new_state[i + 1][j] = 0
        } else if (direction == "left") {
            new_state[i][j] = new_state[i][j - 1]
            new_state[i][j - 1] = 0
        } else if (direction == "right") {
            new_state[i][j] = new_state[i][j + 1]
            new_state[i][j + 1] = 0
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)

        if (i > 0) { moves.add("up") }
        if (i < 2) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < 2) { moves.add("right") }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        open_list.add((this.initial_state, ArrayList<String>()))
        let closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()

        while (open_list.size > 0) {
            let (current_state, path) = open_list.remove(at: 0)
            closed_list.add(current_state)

            if (current_state == this.goal_state) {
                return path
            }

            for (move in get_possible_moves(current_state)) {
                let new_state = move(current_state, move)
                let found = false
                for (closed_state in closed_list) {
                    if (closed_state == new_state) {
                        found = true
                        break
                    }
                }
                if (!found) {
                    let new_path = ArrayList<String>(path)
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }
        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {
    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (!recv.is_full_with_one_more_email(size)) {
            let timestamp = DateTime.now().format("%Y-%m-%d %H:%M:%S")
            let email = HashMap<String, Any>([
                ("sender", this.addr),
                ("receiver", recv.addr),
                ("content", content),
                ("size", size),
                ("time", timestamp),
                ("state", "unread")
            ])
            recv.inbox.add(email, at: recv.inbox.size)
            return true
        } else {
            this.clear_inbox(size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if (this.inbox.size == 0) {
            return None<HashMap<String, Any>>
        }
        for (i in 0..this.inbox.size:1) {
            if (this.inbox[i].get("state") == "unread") {
                this.inbox[i].add("state", "read")
                return this.inbox[i]
            }
        }
        return None<HashMap<String, Any>>
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for (email in this.inbox) {
            occupied_size += email.get("size").getOrThrow() as Int64
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if (this.addr.size == 0) {
            return
        }
        var freed_space: Int64 = 0
        while (freed_space < size && this.inbox.size > 0) {
            let email = this.inbox[0]
            freed_space += email.get("size").getOrThrow() as Int64
            this.inbox.remove(at: 0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let ciphertext = ArrayList<Rune>()
        for (char in plaintext.runes()) {
            if ({ char.isAlpha() }) {
                let ascii_offset = if (char.isUpper()) { r'A'.toInt() } else { r'a'.toInt() }
                let shifted_char = Rune.fromInt((char.toInt() - ascii_offset + shift) %% 26 + ascii_offset)
                ciphertext.add(shifted_char)
            } else {
                ciphertext.add(char)
            }
        }
        return String.fromRuneArray(ciphertext.toArray())
    }

    public func vigenere_cipher(plain_text: String): String {
        let encrypted_text = ArrayList<Rune>()
        var key_index = 0
        for (char in plain_text.runes()) {
            if ({ char.isAlpha() }) {
                let key_char = this.key.runes().get(key_index %% this.key.size()).toLower()
                let shift = key_char.toInt() - r'a'.toInt()
                let encrypted_char = Rune.fromInt((char.toLower().toInt() - r'a'.toInt() + shift) %% 26 + r'a'.toInt())
                encrypted_text.add(if (char.isUpper()) { encrypted_char.toUpper() } else { encrypted_char })
                key_index += 1
            } else {
                encrypted_text.add(char)
            }
        }
        return String.fromRuneArray(encrypted_text.toArray())
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let fence = ArrayList<ArrayList<Rune>>()
        for (_ in 0..rails) {
            fence.add(ArrayList<Rune>())
            for (_ in 0..plain_text.size()) {
                fence.get(fence.size()-1).add(r'\n')
            }
        }
        var direction = -1
        var row: Int64 = 0
        var col: Int64 = 0

        for (char in plain_text.runes()) {
            if (row == 0 || row == rails-1) {
                direction = -direction
            }
            fence.get(row).set(col, char)
            col += 1
            row += direction
        }

        let encrypted_text = ArrayList<Rune>()
        for (i in 0..rails) {
            for (j in 0..plain_text.size()) {
                if (fence.get(i).get(j) != r'\n') {
                    encrypted_text.add(fence.get(i).get(j))
                }
            }
        }
        return String.fromRuneArray(encrypted_text.toArray())
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {
    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(this.transform(expression))

        let result_stack = ArrayList<String>()
        this.postfix_stack.reverse()

        while (this.postfix_stack.size > 0) {
            let current_op = this.postfix_stack.pop()
            if (!this.is_operator(current_op)) {
                let replaced = current_op.replace("~", "-")
                result_stack.add(replaced)
            } else {
                let second_value = result_stack.pop()
                let first_value = result_stack.pop()

                let temp_result = this._calculate(
                    Decimal(first_value.replace("~", "-")),
                    Decimal(second_value.replace("~", "-")),
                    current_op
                )
                result_stack.add(temp_result.toString())
            }
        }

        return Float64(result_stack[0])
    }

    public func prepare(expression: String): Unit {
        let op_stack = ArrayList<String>([","])
        let arr = expression.toRuneArray()
        var current_index = 0
        var count = 0

        for (i, current_op) in arr.enumerate() {
            let op_str = current_op.toString()
            if (this.is_operator(op_str)) {
                if (count > 0) {
                    let segment = arr.slice(current_index, current_index+count).join("")
                    this.postfix_stack.add(segment)
                }
                let peek_op = op_stack[op_stack.size-1]
                if (op_str == ")") {
                    while (op_stack[op_stack.size-1] != "(") {
                        this.postfix_stack.add(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while (op_str != "(" && peek_op != "," && this.compare(op_str, peek_op)) {
                        this.postfix_stack.add(op_stack.pop())
                        let peek_op = op_stack[op_stack.size-1]
                    }
                    op_stack.add(op_str)
                }
                count = 0
                current_index = i+1
            } else {
                count += 1
            }
        }

        if (count > 1 || (count == 1 && !this.is_operator(arr[current_index].toString()))) {
            let segment = arr.slice(current_index, current_index+count).join("")
            this.postfix_stack.add(segment)
        }

        while (op_stack[op_stack.size-1] != ",") {
            this.postfix_stack.add(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_op = if (cur == "%") { "/" } else { cur }
        let peek_op = if (peek == "%") { "/" } else { peek }
        return this.operat_priority[ord(peek_op) - 40] >= this.operat_priority[ord(cur_op) - 40]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            case _ => throw "Unexpected operator: ${current_op}"
        }
    }

    public static func transform(expression: String): String {
        let expr = Regex(r"\s+").replace(expression, "")
                         .replace(r"=$", "")
        let arr = expr.toRuneArray()

        for (i, c) in arr.enumerate() {
            if (c.toString() == "-") {
                if (i == 0) {
                    arr[i] = '~'
                } else {
                    let prev_c = arr[i-1]
                    if (["+", "-", "*", "/", "(", "E", "e"].contains(prev_c.toString())) {
                        arr[i] = '~'
                    }
                }
            }
        }

        if (arr[0].toString() == "~" && arr.size > 1 && arr[1].toString() == "(") {
            arr[0] = '-'
            return "0" + arr.join("")
        } else {
            return arr.join("")
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {
    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        let BMI = this.get_BMI()
        let BMI_range = if (this.sex == "male") {
            this.BMI_std[0]["male"]
        } else {
            this.BMI_std[1]["female"]
        }

        if (BMI > BMI_range[1]) {
            // too fat
            return 1
        } else if (BMI < BMI_range[0]) {
            // too thin
            return -1
        } else {
            // normal
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        let BMR = if (this.sex == "male") {
            10.0 * this.weight + 6.25 * this.height - 5.0 * Float64(this.age) + 5.0
        } else {
            10.0 * this.weight + 6.25 * this.height - 5.0 * Float64(this.age) - 161.0
        }

        let condition = this.condition_judge()
        if (condition == 1) {
            return BMR * 1.2  // Sedentary lifestyle
        } else if (condition == -1) {
            return BMR * 1.6  // Active lifestyle
        } else {
            return BMR * 1.4  // Moderate lifestyle
        }
    }
}

import std.collection.ArrayList

class GomokuGame {
    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (board[row][col] == " ") {
            board[row][col] = current_player
            current_player = if (current_player == "X") { "O" } else { "X" }
            true
        } else {
            false
        }
    }

    public func check_winner(): Option<String> {
        let directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for (row in 0..board_size) {
            for (col in 0..board_size) {
                if (board[row][col] != " ") {
                    for (direction in directions) {
                        if (_check_five_in_a_row(row, col, direction)) {
                            return Some<String>(board[row][col])
                        }
                    }
                }
            }
        }
        None<String>()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let symbol = board[row][col]
        var count = 1
        for (i in 1..5) {
            let new_row = row + dx * i
            let new_col = col + dy * i
            if (!(0 <= new_row < board_size && 0 <= new_col < board_size)) {
                false
            }
            if (board[new_row][new_col] != symbol) {
                false
            }
            count = count + 1
        }
        count == 5
    }
}

import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if (!this.available_rooms.containsKey(room_type)) {
            return "false"
        }
        let available = this.available_rooms.get(room_type).getOrThrow()
        if (room_number <= available) {
            if (!this.booked_rooms.containsKey(room_type)) {
                this.booked_rooms.add(room_type, HashMap<String, Int64>())
            }
            let booked = this.booked_rooms.get(room_type).getOrThrow()
            if (booked.containsKey(name)) {
                let current = booked.get(name).getOrThrow()
                booked.add(name, current + room_number)
            } else {
                booked.add(name, room_number)
            }
            this.available_rooms.add(room_type, available - room_number)
            return "Success!"
        } else if (available != 0) {
            return available.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!this.booked_rooms.containsKey(room_type)) {
            return false
        }
        let booked_type = this.booked_rooms.get(room_type).getOrThrow()
        if (!booked_type.containsKey(name)) {
            return false
        }
        let booked_num = booked_type.get(name).getOrThrow()
        if (room_number > booked_num) {
            return false
        } else if (room_number == booked_num) {
            booked_type.remove(name)
            return true
        } else {
            booked_type.add(name, booked_num - room_number)
            return true
        }
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if (this.available_rooms.containsKey(room_type)) {
            let current = this.available_rooms.get(room_type).getOrThrow()
            this.available_rooms.add(room_type, current + room_number)
        } else {
            this.available_rooms.add(room_type, room_number)
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        if (this.available_rooms.containsKey(room_type)) {
            return this.available_rooms.get(room_type).getOrThrow()
        } else {
            return 0
        }
    }
}

