class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let octets = this.ip_address.split(".")
        if (octets.size != 4) {
            return false
        }
        for (octet in octets) {
            match (Parsable.parseInt(octet)) {
                case Some<Int64>(num) => {
                    if (num < 0 || num > 255) {
                        return false
                    }
                }
                case None<Int64> => return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>([])
        }
        return ArrayList<String>(this.ip_address.split("."))
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let binary_octets = ArrayList<String>()
        for (octet in this.get_octets()) {
            let num = Parsable.parseInt(octet).getOrThrow()
            binary_octets.add(Formattable.format(num, "08b"))
        }
        return binary_octets.join(".")
    }
}

