import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var P0 = 0.0
        for (i in 0..k) {
            P0 += testData[i][i].toFloat64()
        }

        var xsum = ArrayList<Int64>()
        var ysum = ArrayList<Int64>()
        var sum = 0

        // Calculate row sums (xsum)
        for (row in testData) {
            var rowSum = 0
            for (val in row) {
                rowSum += val
            }
            xsum.add(rowSum)
        }

        // Calculate column sums (ysum) and total sum
        for (i in 0..k) {
            var colSum = 0
            for (j in 0..k) {
                colSum += testData[j][i]
            }
            ysum.add(colSum)
            sum += colSum
        }

        var Pe = 0.0
        for (i in 0..k) {
            Pe += xsum[i].toFloat64() * ysum[i].toFloat64()
        }
        Pe /= sum.toFloat64() * sum.toFloat64()

        P0 /= sum.toFloat64()
        return (P0 - Pe) / (1 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var sum = 0.0
        var P0 = 0.0

        for (i in 0..N) {
            var temp = 0.0
            for (j in 0..k) {
                sum += testData[i][j].toFloat64()
                temp += testData[i][j].toFloat64() * testData[i][j].toFloat64()
            }
            temp -= n.toFloat64()
            temp /= (n.toFloat64() - 1.0) * n.toFloat64()
            P0 += temp
        }

        P0 /= N.toFloat64()

        var ysum = ArrayList<Float64>()
        for (j in 0..k) {
            var colSum = 0.0
            for (i in 0..N) {
                colSum += testData[i][j].toFloat64()
            }
            ysum.add(colSum)
        }

        var Pe = 0.0
        for (j in 0..k) {
            Pe += (ysum[j] / sum) * (ysum[j] / sum)
        }

        return (P0 - Pe) / (1 - Pe)
    }
}

