import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {
    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let board = ArrayList<ArrayList<String>>()
        for (_ in 0..BOARD_SIZE[0]) {
            let row = ArrayList<String>()
            for (_ in 0..BOARD_SIZE[1]) {
                row.add(Random.choice(ICONS))
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        if not (0 <= x1 < BOARD_SIZE[0] and 0 <= y1 < BOARD_SIZE[1] and 
               0 <= x2 < BOARD_SIZE[0] and 0 <= y2 < BOARD_SIZE[1]) {
            return false
        }

        if pos1 == pos2 {
            return false
        }

        if board[x1][y1] != board[x2][y2] {
            return false
        }

        if not has_path(pos1, pos2) {
            return false
        }

        return true
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = HashSet<(Int64, Int64)>()
        let stack = ArrayList<(Int64, Int64)>()
        stack.add(pos1)

        while (stack.size > 0) {
            let current_pos = stack.remove(at: stack.size - 1)
            if current_pos == pos2 {
                return true
            }

            if visited.contains(current_pos) {
                continue
            }

            visited.add(current_pos)
            let x = current_pos[0]
            let y = current_pos[1]

            for (dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]) {
                let new_x = x + dx
                let new_y = y + dy
                if 0 <= new_x < BOARD_SIZE[0] and 0 <= new_y < BOARD_SIZE[1] {
                    if not visited.contains((new_x, new_y)) and board[new_x][new_y] == board[x][y] {
                        stack.add((new_x, new_y))
                    }
                }
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (icon in row) {
                if icon != " " {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center - diff == -1 || center + diff == string.runes().size || 
            string.toRuneArray()[center - diff] != string.toRuneArray()[center + diff]) {
            return 0
        }
        return 1 + self.palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        var max_length: Int64 = 0
        var new_input_string: String = ""
        var output_string: String = ""
        let rune_array = self.input_string.toRuneArray()

        for (i in 0..rune_array.size - 1) {
            new_input_string += rune_array[i].toString() + "|"
        }
        new_input_string += rune_array[rune_array.size - 1].toString()

        for (i in 0..new_input_string.toRuneArray().size) {
            let length = self.palindromic_length(i, 1, new_input_string)
            if (max_length < length) {
                max_length = length
                let start = i
                output_string = ""
                for (r in new_input_string.toRuneArray()[start - max_length..start + max_length + 1]) {
                    if (r != r'|') {
                        output_string += r.toString()
                    }
                }
            }
        }
        return output_string
    }
}

import std.collection.ArrayList
