import std.convert.Parsable

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64,operation_k: Int64): ArrayList<ArrayList<String>> {
        let arr = ArrayList<ArrayList<String>>()
        for i in 0..n {
            let row = ArrayList<String>()
            for j in 0..n {
                row.add("0")
            }
            arr.add(row)
        }

        var k = operation_k
        while (k > 0) {
            let x = Random.randInt(0, n)
            let y = Random.randInt(0, n)

            if (arr.get(y.toInt64()).get(x.toInt64()) != "X") {
                arr.get(y.toInt64()).set(x.toInt64(), "X")
                k -= 1

                for i in -1..2 {
                    for j in -1..2 {
                        let nx = x + i
                        let ny = y + j

                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && arr.get(ny).get(nx) != "X") {
                            let current = arr.get(ny).get(nx)
                            let parsed = current.parseInt().getOrThrow()
                            arr.get(ny).set(nx, (parsed + 1).toString())
                        }
                    }
                }
            }
        }
        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let arr = ArrayList<ArrayList<String>>()
        for i in 0..n {
            let row = ArrayList<String>()
            for j in 0..n {
                row.add("-")
            }
            arr.add(row)
        }
        return arr
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..n {
            for j in 0..n {
                if (map.get(i).get(j) == "-" && minesweeper_map.get(i).get(j) != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map.get(x).get(y) == "X") {
            return false
        } else {
            player_map.get(x).set(y, minesweeper_map.get(x).get(y))
            score += 1
            if (check_won(player_map)) {
                return true
            }
            return player_map
        }
    }
}

