import std.unicode.UnicodeStringExtension

class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some<String>(val) => this.format_string(val)
            case None<String> => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let lstr = parts[0]
        let rstr = if (parts.size > 1) { parts[1] } else { "" }

        let lstrrev = lstr.reverse()
        let mut a: Array<String> = ["", "", "", "", ""]

        if (lstrrev.size % 3 == 1) {
            lstrrev += "00"
        } else if (lstrrev.size % 3 == 2) {
            lstrrev += "0"
        }

        let mut lm = ""
        for (i in 0..(lstrrev.size / 3)) {
            let start = 3 * i
            let end = 3 * i + 3
            a[i] = lstrrev.substr(start, end).reverse()
            if (a[i] != "000") {
                lm = this.trans_three(a[i]) + " " + this.parse_more(Int64(i)) + " " + lm
            } else {
                lm += this.trans_three(a[i])
            }
        }

        let xs = if (rstr != "") { 
            "AND CENTS " + this.trans_two(rstr) + " " 
        } else { 
            "" 
        }

        if (lm.trim() == "") {
            "ZERO ONLY"
        } else {
            lm.trim() + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        let s_padded = s.zfill(2)
        if (s_padded[0] == r'0') {
            this.NUMBER[Int64(s_padded[1].toString())]
        } else if (s_padded[0] == r'1') {
            this.NUMBER_TEEN[Int64(s_padded) - 10]
        } else if (s_padded[1] == r'0') {
            this.NUMBER_TEN[Int64(s_padded[0].toString()) - 1]
        } else {
            this.NUMBER_TEN[Int64(s_padded[0].toString()) - 1] + " " + this.NUMBER[Int64(s_padded[1].toString())]
        }
    }

    public func trans_three(s: String): String {
        if (s[0] == r'0') {
            this.trans_two(s.substr(1))
        } else if (s.substr(1) == "00") {
            this.NUMBER[Int64(s[0].toString())] + " HUNDRED"
        } else {
            this.NUMBER[Int64(s[0].toString())] + " HUNDRED AND " + this.trans_two(s.substr(1))
        }
    }

    public func parse_more(i: Int64): String {
        this.NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        var pos = 0
        let length = string.toRuneArray().size

        while (pos < length - 2) {
            let runes = string.toRuneArray()
            if (runes[pos] == r'&' && runes[pos + 1] == r'#') {
                var start = pos + 2
                var is_hex = false
                let first_char = runes[start]

                if (first_char == r'x' || first_char == r'X') {
                    start += 1
                    is_hex = true
                }

                if (start == length) {
                    return out.toRuneArray().toString()
                }

                var end = start
                while (end < length && NumericEntityUnescaper.is_hex_char(runes[end])) {
                    end += 1
                }

                if (end < length && runes[end] == r';') {
                    let entity_str = runes.slice(start, end).toString()
                    let entity_value = 
                        if (is_hex) { entity_str.toInt(radix: 16) } 
                        else { entity_str.toInt() }

                    if (entity_value.isSome()) {
                        out.add(runes.slice(0, pos))
                        out.add(entity_value.getOrThrow().toRune())
                        pos = end + 1
                        continue
                    }
                }
            }
            out.add(string.toRuneArray()[pos])
            pos += 1
        }

        return out.toRuneArray().toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        let c = char.charCode()
        return (c >= r'0'.charCode() && c <= r'9'.charCode()) ||
               (c >= r'a'.charCode() && c <= r'f'.charCode()) ||
               (c >= r'A'.charCode() && c <= r'F'.charCode())
    }
}

