class Order {
    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        for (var i = 0; i < this.menu.size(); i += 1) {
            if (dish.dish == this.menu[i].dish) {
                if (this.menu[i].count < dish.count) {
                    return false
                } else {
                    this.menu[i].count -= dish.count
                    this.selected_dishes.add(dish)
                    return true
                }
            }
        }
        return false
    }

    public func calculate_total(): Float64 {
        var total: Float64 = 0.0
        for (var i = 0; i < this.selected_dishes.size(); i += 1) {
            let dish = this.selected_dishes[i]
            let sale = this.sales.get(dish.dish) ?? 1.0
            total += dish.price.toFloat64() * dish.count.toFloat64() * sale
        }
        return total
    }

    public func checkout(): Option<Float64> {
        if (this.selected_dishes.size() == 0) {
            return None<Float64>
        }
        let total = this.calculate_total()
        this.selected_dishes.clear()
        return Some<Float64>(total)
    }
}

import std.collection.ArrayList

class PageUtil {

    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        if (page_number < 1 || page_number > this.total_pages) {
            return ArrayList<Int64>([])
        }

        let start_index = (page_number - 1) * this.page_size
        let end_index = min(start_index + this.page_size, this.total_items)
        var result = ArrayList<Int64>([])

        for (i in start_index..end_index) {
            result.add(this.data[i])
        }
        return result
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if (page_number < 1 || page_number > this.total_pages) {
            return None<PageInfo>
        }

        let page_data = this.get_page(page_number)
        return Some<PageInfo>(PageInfo(
            current_page: page_number,
            per_page: this.page_size,
            total_pages: this.total_pages,
            total_items: this.total_items,
            has_previous: page_number > 1,
            has_next: page_number < this.total_pages,
            data: page_data
        ))
    }

    public func search(keyword: String): SearchInfo {
        var results = ArrayList<Int64>([])

        for (item in this.data) {
            if (keyword == item.toString()) {
                results.add(item)
            }
        }

        let num_results = results.size
        let num_pages = (num_results + this.page_size - 1) / this.page_size

        return SearchInfo(
            keyword: keyword,
            total_results: num_results,
            total_pages: num_pages,
            results: results
        )
    }
}

class PersonRequest {
    let name: Option<String>
    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        this.name = _validate_name(name)
        this.sex = _validate_sex(sex)
        this.phoneNumber = _validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        if (name.isEmpty() || name.size() > 33) {
            return None<String>()
        }
        return Some<String>(name)
    }

    public static func _validate_sex(sex: String): Option<String> {
        match (sex) {
            case "Man" => return Some<String>(sex)
            case "Woman" => return Some<String>(sex)
            case "UGM" => return Some<String>(sex)
            case _ => return None<String>()
        }
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        if (phoneNumber.isEmpty() || phoneNumber.size() != 11) {
            return None<String>()
        }

        let isDigit = {c: Rune => c >= r'0' && c <= r'9'}
        for (c in phoneNumber.runes()) {
            if (!isDigit(c)) {
                return None<String>()
            }
        }

        return Some<String>(phoneNumber)
    }
}

import std.collection.ArrayList

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<(Int64, Int64)>
    let boxes: ArrayList<(Int64, Int64)>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<(Int64, Int64)>()
        this.boxes = ArrayList<(Int64, Int64)>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i, row) in this.map.enumerated() {
                for (j, cell) in row.enumerated() {
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add((i, j))
                        this.target_count += 1
                    } else if (cell == "X") {
                        this.boxes.add((i, j))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_on_target_count: Int64 = 0
        for box in this.boxes {
            if (this.targets.contains(box)) {
                box_on_target_count += 1
            }
        }
        this.is_game_over = box_on_target_count == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_player_row = this.player_row
        var new_player_col = this.player_col

        if (direction == "w") {
            new_player_row -= 1
        } else if (direction == "s") {
            new_player_row += 1
        } else if (direction == "a") {
            new_player_col -= 1
        } else if (direction == "d") {
            new_player_col += 1
        }

        if (this.map[new_player_row][new_player_col] != "#") {
            let new_pos = (new_player_row, new_player_col)
            if (this.boxes.contains(new_pos)) {
                let new_box_row = new_player_row + (new_player_row - this.player_row)
                let new_box_col = new_player_col + (new_player_col - this.player_col)
                let new_box_pos = (new_box_row, new_box_col)

                if (this.map[new_box_row][new_box_col] != "#") {
                    this.boxes.remove(new_pos)
                    this.boxes.add(new_box_pos)
                    this.player_row = new_player_row
                    this.player_col = new_player_col
                }
            } else {
                this.player_row = new_player_row
                this.player_col = new_player_col
            }
        }

        return this.check_win()
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex(pattern)
        return regex.match(text).isSome()
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (m in matches) {
            result.add(m.group(0))
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let parts = regex.split(text)
        return ArrayList<String>(parts)
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex(pattern)
        return regex.replaceAll(text, replacement)
    }

    public func generate_email_pattern(): String {
        return r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    }

    public func generate_phone_number_pattern(): String {
        return r'\b\d{3}-\d{3}-\d{4}\b'
    }

    public func generate_split_sentences_pattern(): String {
        return r'[.!?][\s]{1,2}(?=[A-Z])'
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = this.generate_split_sentences_pattern()
        return this.split(pattern, text)
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = this.generate_phone_number_pattern()
        return this.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = this.generate_email_pattern()
        return this.findall(pattern, text)
    }
}

class RPGCharacter {
    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = max(this.attack_power - other_character.defense, 1)
        other_character.hp -= damage
    }

    public func heal(): Int64 {
        this.hp += 10
        if (this.hp > 100) {
            this.hp = 100
        }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        var remaining_amount = amount
        while (remaining_amount != 0) {
            if (this.exp + remaining_amount >= this.level * 100) {
                remaining_amount -= (this.level * 100 - this.exp)
                this.level_up()
            } else {
                this.exp += remaining_amount
                remaining_amount = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level < 100) {
            this.level += 1
            this.exp = 0
            this.hp += 20
            this.attack_power += 5
            this.defense += 5
        }
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        if (this.white_list.contains(addr)) {
            return None<ArrayList<Int64>>()
        } else {
            this.white_list.add(addr)
            return Some<ArrayList<Int64>>(this.white_list)
        }
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        if (!this.white_list.contains(addr)) {
            return None<ArrayList<Int64>>()
        } else {
            this.white_list.remove(at: this.white_list.indexOf(addr))
            return Some<ArrayList<Int64>>(this.white_list)
        }
    }

    public func recv(info: HashMap<String, Any>): Any {
        if (!info.contains("addr") || !info.contains("content")) {
            return -1
        }
        let addr = info["addr"]
        let content = info["content"]
        if (!white_list.contains(addr)) {
            return false
        } else {
            this.receive_struct = HashMap<String, Any>([("addr", addr), ("content", content)])
            return this.receive_struct["content"]
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        if (!info.contains("addr") || !info.contains("content")) {
            return Some<String>("info structure is not correct")
        }
        this.send_struct = HashMap<String, Any>([("addr", info["addr"]), ("content", info["content"])])
        return None<String>()
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
