import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let cur = this.positions[0]
        let x = direction[0]
        let y = direction[1]

        let new_x = (cur[0] + (x * this.BLOCK_SIZE)) % this.SCREEN_WIDTH
        let new_y = (cur[1] + (y * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT
        let new = ArrayList<Int64>([new_x, new_y])

        if (new == this.food_position) {
            this.eat_food()
        }

        if (this.positions.size > 2) {
            let body_positions = ArrayList<ArrayList<Int64>>(this.positions[2..this.positions.size])
            if (body_positions.contains(new)) {
                this.reset()
                return
            }
        }

        this.positions.add(new, at: 0)
        if (this.positions.size > this.length) {
            this.positions.remove(at: this.positions.size - 1)
        }
    }

    public func random_food_position(): Unit {
        let random = Random()
        while (true) {
            let x = random.nextRange(0, (this.SCREEN_WIDTH / this.BLOCK_SIZE) - 1) * this.BLOCK_SIZE
            let y = random.nextRange(0, (this.SCREEN_HEIGHT / this.BLOCK_SIZE) - 1) * this.BLOCK_SIZE
            let new_food = ArrayList<Int64>([x, y])

            if (!this.positions.contains(new_food)) {
                this.food_position = new_food
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = Regex(r"(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s")
        let sentences = ArrayList<String>()
        let parts = pattern.split(sentences_string)
        for part in parts {
            if (!part.isEmpty()) {
                sentences.add(part)
            }
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        let clean_sentence = Regex(r"[^a-zA-Z\s]").replaceAll(sentence, "")
        let words = clean_sentence.split(" ")
        return words.size.toInt64()
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = this.split_sentences(sentences_string)
        var max_count: Int64 = 0
        for sentence in sentences {
            let count = this.count_words(sentence)
            if (count > max_count) {
                max_count = count
            }
        }
        return max_count
    }
}

