class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        let cols = if (columns[0] == "*") { "*" } else { columns.join(", ") }
        var query = "SELECT ${cols} FROM ${table}"

        match (where_condition) {
            case Some(cond) => {
                let conditions = ArrayList<String>()
                for ((k, v) in cond) {
                    conditions.add("${k}='${v}'")
                }
                query += " WHERE " + conditions.join(" AND ")
            }
            case None => {}
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        let keys = data.keys().join(", ")
        let values = ArrayList<String>()
        for (v in data.values()) {
            values.add("'${v}'")
        }
        return "INSERT INTO ${table} (${keys}) VALUES (${values.join(", ")})"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM ${table}"

        match (where_condition) {
            case Some(cond) => {
                let conditions = ArrayList<String>()
                for ((k, v) in cond) {
                    conditions.add("${k}='${v}'")
                }
                query += " WHERE " + conditions.join(" AND ")
            }
            case None => {}
        }
        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        let updates = ArrayList<String>()
        for ((k, v) in data) {
            updates.add("${k}='${v}'")
        }
        var query = "UPDATE ${table} SET ${updates.join(", ")}"

