                    conditions.add("${k}='${v}'")
                }
                query += " WHERE " + conditions.join(" AND ")
            }
            case None => {}
        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = data.copy()
        sort(sorted_data)
        let n = sorted_data.size
        if (n % 2 == 1) {
            return sorted_data[n // 2].toFloat64()
        } else {
            return (sorted_data[n // 2 - 1] + sorted_data[n // 2]).toFloat64() / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for (value in data) {
            counts.add(value, counts.get(value) ?? 0 + 1)
        }
        let max_count = counts.values().max() ?? 0
        let mode_values = ArrayList<Int64>()
        for ((value, count) in counts) {
            if (count == max_count) {
                mode_values.add(value)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if (n == 0 || n != y.size) {
            return None<Float64>
        }
        let mean_x = (x.sum() as Int64).toFloat64() / n.toFloat64()
        let mean_y = (y.sum() as Int64).toFloat64() / n.toFloat64()

        var numerator = 0.0
        var denom_x = 0.0
        var denom_y = 0.0

        for (i in 0..n) {
            let xi_diff = x[i].toFloat64() - mean_x
            let yi_diff = y[i].toFloat64() - mean_y
            numerator += xi_diff * yi_diff
            denom_x += xi_diff * xi_diff
            denom_y += yi_diff * yi_diff
        }

        let denominator = sqrt(denom_x * denom_y)
        if (denominator == 0.0) {
            return None<Float64>
        }
        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n == 0) {
            return None<Float64>
        }
        return Some<Float64>((data.sum() as Int64).toFloat64() / n.toFloat64())
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let matrix = ArrayList<ArrayList<Float64>>()
        let cols = if (data.size > 0) { data[0].size } else { 0 }

        for (i in 0..cols) {
            let row = ArrayList<Float64>()
            for (j in 0..cols) {
                let column1 = ArrayList<Int64>()
                let column2 = ArrayList<Int64>()

                for (d in data) {
                    column1.add(d[i])
                    column2.add(d[j])
                }

                let corr = correlation(column1, column2)
                row.add(corr ?? Float64.NaN)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n < 2) {
            return None<Float64>
        }
        let mean_value = mean(data).getOrThrow()
        var variance = 0.0

        for (x in data) {
            let diff = x.toFloat64() - mean_value
            variance += diff * diff
        }

        variance /= (n - 1).toFloat64()
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_value = mean(data)
        let std_deviation = standard_deviation(data)

        if (mean_value is None<Float64> || std_deviation is None<Float64> || std_deviation.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>
        }

        let result = ArrayList<Float64>()
        for (x in data) {
            result.add((x.toFloat64() - mean_value.getOrThrow()) / std_deviation.getOrThrow())
        }
        return Some<ArrayList<Float64>>(result)
    }
}

