class TicTacToe {
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (this.board[row][col] == " ") {
            this.board[row][col] = this.current_player
            this.current_player = if (this.current_player == "X") { "O" } else { "X" }
            return true
        }
        return false
    }

    public func check_winner(): Option<String> {
        // Check rows
        for (row in 0..3) {
            if (this.board[row][0] != " " && this.board[row][0] == this.board[row][1] && this.board[row][1] == this.board[row][2]) {
                return Some<String>(this.board[row][0])
            }
        }

        // Check columns
        for (col in 0..3) {
            if (this.board[0][col] != " " && this.board[0][col] == this.board[1][col] && this.board[1][col] == this.board[2][col]) {
                return Some<String>(this.board[0][col])
            }
        }

        // Check diagonals
        if (this.board[0][0] != " " && this.board[0][0] == this.board[1][1] && this.board[1][1] == this.board[2][2]) {
            return Some<String>(this.board[0][0])
        }
        if (this.board[0][2] != " " && this.board[0][2] == this.board[1][1] && this.board[1][1] == this.board[2][0]) {
            return Some<String>(this.board[0][2])
        }

        return None<String>
    }

    public func is_board_full(): Bool {
        for (row in 0..3) {
            for (col in 0..3) {
                if (this.board[row][col] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

