import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        return round(this.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        var b: Decimal = Decimal(1)
        var current = a
        while (current != 1) {
            b = b * Decimal(current)
            current -= 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a = 1.0
        let x_rad = x / 180.0 * this.PI
        var count = 1
        for (k in 1..n) {
            if (count % 2 != 0) {
                a -= (x_rad ** Float64(2 * k)) / this.factorial(2 * k).toFloat64()
            } else {
                a += (x_rad ** Float64(2 * k)) / this.factorial(2 * k).toFloat64()
            }
            count += 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        let x_rad = x / 180.0 * this.PI
        var g = 0.0
        var t = x_rad
        var n = 1

        while (abs(t) >= 1e-15) {
            g += t
            n += 1
            t = -t * x_rad * x_rad / Float64(2 * n - 1) / Float64(2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = this.cos(x)
        if (abs(cos_val - 0.0) > 0.000001) {
            return Some<Float64>(round(this.sin(x) / cos_val, 10))
        } else {
            return None<Float64>
        }
    }
}

