    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {
    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        this.nums.clear()
        for (_ in 0..4) {
            this.nums.add(Random.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums.copy()
    }

    public func answer(expression: String): Bool {
        if (expression == "pass") {
            this._generate_cards()
            return false
        }

        let statistic = HashMap<Rune, Int64>()
        for c in expression.runes() {
            if (c.isAsciiNumber()) {
                let num = Int64.parse(Rune.toString(c))
                if (this.nums.contains(num)) {
                    statistic[c] = statistic.get(c) ?? 0 + 1
                }
            }
        }

        var nums_used = statistic.copy()

        for num in this.nums {
            let c = Rune.fromInt(num)
            let count = nums_used.get(c) ?? -100
            if (count != -100 && count > 0) {
                nums_used[c] = count - 1
            } else {
                return false
            }
        }

        if (nums_used.values().all({count => count == 0})) {
            return this.evaluate_expression(expression)
        }
        return false
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (e: Exception) {
            return false
        }
    }
}

import std.collection.HashMap

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            return Some(url.substring(0, scheme_end))
        }
        return None<String>()
    }

    public func get_host(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            let url_without_scheme = url.substring(scheme_end + 3)
            let host_end = url_without_scheme.find("/")
            if (host_end != -1) {
                return Some(url_without_scheme.substring(0, host_end))
            } else {
                return Some(url_without_scheme)
            }
        }
        return None<String>()
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            let url_without_scheme = url.substring(scheme_end + 3)
            let host_end = url_without_scheme.find("/")
            if (host_end != -1) {
                return Some(url_without_scheme.substring(host_end))
            }
        }
        return None<String>()
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.find("?")
        let fragment_start = url.find("#")
        if (query_start != -1) {
            let query_end = if (fragment_start != -1) { fragment_start } else { url.size }
            let query_string = url.substring(query_start + 1, query_end)
            let params = HashMap<String, String>()
            if (query_string.size > 0) {
                let param_pairs = query_string.split("&")
                for pair in param_pairs {
                    let key_value = pair.split("=")
                    if (key_value.size == 2) {
                        params.add(key_value[0], key_value[1])
                    }
                }
            }
            return Some(params)
        }
        return None<HashMap<String, String>>()
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.find("#")
        if (fragment_start != -1) {
            return Some(url.substring(fragment_start + 1))
        }
        return None<String>()
    }
}

import std.collection.ArrayList

class UrlPath {
    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment, at: segments.size)
    }

    public func parse(path: String, charset: String): Unit {
        if (path != "") {
            this.with_end_tag = path.endsWith("/")
            let fixed_path = UrlPath.fix_path(path)
            if (fixed_path != "") {
                let split = fixed_path.split("/")
                for (seg in split) {
                    let decoded_seg = seg.unquote(charset)
                    this.segments.add(decoded_seg, at: segments.size)
                }
            }
        }
    }

    public static func fix_path(path: String): String {
        if (path == "") {
            return ""
        }
        return path.strip("/")
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let v1 = unitvec(vector_1)
        let v2 = unitvec(vector_2)
        return dotProduct(v1, v2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm = vectorNorm(vector_1)
        let all_norms = ArrayList<Float64>()
        let dot_products = ArrayList<Float64>()

        for vec in vectors_all {
            all_norms.add(vectorNorm(vec))
            dot_products.add(dotProduct(vector_1, vec))
        }

        let similarities = ArrayList<Float64>()
        for i in 0..dot_products.size {
            similarities.add(dot_products[i] / (norm * all_norms[i]))
        }
        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            throw "At least one of the passed list is empty."
        }

        let mean1 = computeMeanVector(vector_list_1)
        let mean2 = computeMeanVector(vector_list_2)
        return similarity(mean1, mean2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let index_2_key_map = HashMap<Int64, String>()
        let count_list = ArrayList<Float64>()
        let keys = number_dict.keys()

        for (index, key) in keys.enumerate() {
            index_2_key_map.add(index, key)
            count_list.add(number_dict[key])
        }

        let result = HashMap<String, Float64>()
        for (index, count) in count_list.enumerate() {
            let w = log((Float64(total_num) + 1.0) / (count + 1.0))
            result.add(index_2_key_map[index], w)
        }
        return result
    }

    private static func dotProduct(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for i in 0..v1.size {
            sum = sum + v1[i] * v2[i]
        }
        return sum
    }

    private static func vectorNorm(v: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for val in v {
            sum = sum + val * val
        }
        return sqrt(sum)
    }

    private static func unitvec(v: ArrayList<Float64>): ArrayList<Float64> {
        let norm = vectorNorm(v)
        let result = ArrayList<Float64>()
        for val in v {
            result.add(val / norm)
        }
        return result
    }

    private static func computeMeanVector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        if (vectors.size == 0) {
            return ArrayList<Float64>()
        }

        let dim = vectors[0].size
        let result = ArrayList<Float64>()
        for _ in 0..dim {
            result.add(0.0)
        }

        for vec in vectors {
            for i in 0..dim {
                result[i] = result[i] + vec[i]
            }
        }

        for i in 0..dim {
            result[i] = result[i] / Float64(vectors.size)
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {
    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {
    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        if (!this.restock_item(item_name, quantity)) {
            this.inventory.add(item_name, Product(price, quantity))
        }
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        match (this.inventory.get(item_name)) {
            case Some<Product>(product) => {
                if (product.quantity > 0 && this.balance >= product.price) {
                    this.balance -= product.price
                    product.quantity -= 1
                    return Some<Float64>(this.balance)
                } else {
                    return None<Float64>
                }
            }
            case None<Product> => return None<Float64>
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        match (this.inventory.get(item_name)) {
            case Some<Product>(product) => {
                product.quantity += quantity
                return true
            }
            case None<Product> => return false
        }
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None<String>
        } else {
            let items = ArrayList<String>()
            for (item_name, product) in this.inventory {
                items.add("${item_name} - $${product.price} [${product.quantity}]")
            }
            return Some<String>(items.join("\n"))
        }
    }
}

import std.collection.HashMap

class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            this.inventory[product_id].quantity += quantity
        } else {
            this.inventory.add(product_id, Product(name, quantity))
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            this.inventory[product_id].quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if (this.inventory.contains(product_id)) {
            return Some<Int64>(this.inventory[product_id].quantity)
        } else {
            return None<Int64>
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        let curr_quantity = this.get_product_quantity(product_id)
        if (curr_quantity is None<Int64> || curr_quantity.getOrThrow() < quantity) {
            return false
        } else {
            this.update_product_quantity(product_id, -quantity)
            this.orders.add(order_id, Order(product_id, quantity, "Shipped"))
            return true
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if (this.orders.contains(order_id)) {
            this.orders[order_id].status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if (this.orders.contains(order_id)) {
            return Some<String>(this.orders[order_id].status)
        } else {
            return None<String>
        }
    }
}

